    const [restoredShares, setRestoredShares] = useState<Share[] | ShareWithKey[] | undefined>();

    useEffect(() => {
        const shares = getRestoredPhotosShares();
        setRestoredShares(shares);
        setNeedsRecovery(!!shares?.length);
    }, [getRestoredPhotosShares]);
    const handleFailed = (e: Error) => {
        setState('FAILED');
        setItem(RECOVERY_STATE_CACHE_KEY, 'failed');
        sendErrorReport(e);
    };

    const handleDecryptLinks = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[], includeTrashed = false) => {
            for (const share of shares) {
                await Promise.all([
                    loadChildren(abortSignal, share.shareId, share.rootLinkId),
                    ...(includeTrashed ? [loadTrashedLinks(abortSignal, share.volumeId)] : []),
                ]);
                await waitFor(
                    () => {
                        const { isDecrypting } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
                        return (
                            !isDecrypting &&
                            (!includeTrashed || !getCachedTrashed(abortSignal, share.volumeId).isDecrypting)
                        );
                    },
                    { abortSignal }
                );
            }
        },
        [getCachedChildren, getCachedTrashed, loadChildren, loadTrashedLinks]
    );

    const getRecoveryLinks = useCallback(
        (abortSignal: AbortSignal, share: Share | ShareWithKey, includeTrashed = false) => {
            const { links } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
            const trashed = includeTrashed
                ? getCachedTrashed(abortSignal, share.volumeId).links.filter(
                      (link) =>
                          link.isFile &&
                          (link.mimeType.startsWith('image/') || isVideo(link.mimeType)) &&
                          (link.rootShareId === share.shareId || link.shareId === share.shareId)
                  )
                : [];
            return [...new Map([...links, ...trashed].map((link) => [link.linkId, link])).values()];
        },
        [getCachedChildren, getCachedTrashed]
    );

    const handlePrepareLinks = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            const allRestoredData: { links: DecryptedLink[]; shareId: string }[] = [];
            let totalNbLinks: number = 0;

            for (const share of shares) {
                const links = getRecoveryLinks(abortSignal, share, true);
                allRestoredData.push({
                    links,
                    shareId: share.shareId,
                });
                totalNbLinks += links.length;
            }
            return { allRestoredData, totalNbLinks };
        },
        [getRecoveryLinks]
    );

    const safelyDeleteShares = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            for (const share of shares) {
                if (getRecoveryLinks(abortSignal, share, true).length) {
                    throw new Error('Recovered photos remain in the restored share');
                }
                await deletePhotosShare(share.volumeId, share.shareId);
            }
        },
        [deletePhotosShare, getRecoveryLinks]
    );

    const handleMoveLinks = useCallback(
        async (
            abortSignal: AbortSignal,
            {
                dataList,
                newLinkId,
            }: {
                dataList: { links: DecryptedLink[]; shareId: string }[];
                newLinkId: string;
            }
        ) => {
            for (const data of dataList) {
                if (!data.links.length) {
                    continue;
                }
                const pending = new Set(data.links.map((link) => link.linkId));
                try {
                    await moveLinks(abortSignal, {
                        shareId: data.shareId,
                        linkIds: data.links.map((link) => link.linkId),
                        newParentLinkId: newLinkId,
                        newShareId: shareId,
                        onMoved: (linkId) => {
                            if (pending.delete(linkId)) {
                                setCountOfUnrecoveredLinksLeft((count) => count - 1);
                            }
                        },
                        onError: (linkId) => {
                            if (pending.delete(linkId)) {
                                setCountOfUnrecoveredLinksLeft((count) => count - 1);
                                setCountOfFailedLinks((count) => count + 1);
                            }
                        },
                    });
                } catch (error) {
                    setCountOfFailedLinks((count) => count + pending.size);
                    throw error;
                }
            }
        },
        [moveLinks, shareId]
    );

    useEffect(() => {
        if (state !== 'STARTED' || !linkId || !restoredShares) {
            return;
        }
        const abortController = new AbortController();
        setState('DECRYPTING');
        void handleDecryptLinks(abortController.signal, restoredShares, true)
            .then(() => {
                setState('DECRYPTED');
            })
            .catch(handleFailed);
    }, [handleDecryptLinks, linkId, restoredShares, state]);

    useEffect(() => {
        const abortController = new AbortController();
        if (state !== 'DECRYPTED' || !restoredShares) {
            return;
        }
        setState('PREPARING');
        void handlePrepareLinks(abortController.signal, restoredShares)
            .then(({ allRestoredData, totalNbLinks }) => {
                setRestoredData(allRestoredData);
                setCountOfUnrecoveredLinksLeft(totalNbLinks);
                setState('PREPARED');
            })
            .catch(handleFailed);
        return () => {
            abortController.abort();
        };
    }, [handlePrepareLinks, restoredShares, state]);

    useEffect(() => {
        if (state !== 'PREPARED' || !linkId) {
